// Parse AI response and prepare data for DB save
const choices = $input.all()[0].json.choices || [];
const content = choices[0]?.message?.content || '{}';
const cleaned = content.replace(/```json[\s\S]*?```/g, '').trim() || content.replace(/```json\s*/g, '').replace(/```/g, '').trim();

// Get original webhook data for DB insert
const wb = $('Webhook Publication').first().json.body;

let parsed = {};
try { parsed = JSON.parse(cleaned); } catch(e) {
  // Try harder - extract JSON from response
  const match = content.match(/\{[\s\S]*\}/);
  if (match) try { parsed = JSON.parse(match[0]); } catch(e2) {}
}

const titre = (parsed.titre || parsed.title || 'Publication generee').substring(0, 200);
const message = parsed.message || parsed.description || cleaned;
const type = wb.type || 'DEMANDE_SERVICE';
const userId = parseInt(wb.user_id) || 0;
const budget = parseFloat(wb.budget) || 0;
const categoryId = wb.category_id ? parseInt(wb.category_id) : null;

// SQL-safe escaping
function esc(s) { return String(s).replace(/'/g, "''"); }

const now = new Date().toISOString().slice(0, 19).replace('T', ' ');

return [{ json: {
  titre: titre,
  message: message,
  titre_esc: esc(titre),
  message_esc: esc(message),
  type_publication: type,
  student_id: userId,
  category_id_sql: categoryId ? String(categoryId) : 'NULL',
  prix_vente_sql: (type === 'VENTE_OBJET' && budget > 0) ? budget.toFixed(2) : 'NULL',
  proposed_price_sql: (type !== 'VENTE_OBJET' && budget > 0) ? budget.toFixed(2) : 'NULL',
  created_at: now,
  updated_at: now,
  success: true
}}];

